import CVulkan

public struct Offset2D: CStructConvertible {
    public typealias CStruct = VkOffset2D

    public let x: Int32
    public let y: Int32

    public init(x: Int32, y: Int32) {
        self.x = x
        self.y = y
    }

    init(cStruct: VkOffset2D) {
        self.x = cStruct.x
        self.y = cStruct.y
    }

    public func withCStruct<R, E: Error>(_ body: (UnsafePointer<VkOffset2D>) throws(E) -> R) throws(E) -> R {
        var cStruct = VkOffset2D()
        cStruct.x = self.x
        cStruct.y = self.y
        return try body(&cStruct)
    }
}

