        cStruct.height = self.height
        cStruct.minDepth = self.minDepth
        cStruct.maxDepth = self.maxDepth
        return try body(&cStruct)
    }
}

public struct Rect2D: CStructConvertible {
    public typealias CStruct = VkRect2D

    public let offset: Offset2D
    public let extent: Extent2D

    public init(offset: Offset2D, extent: Extent2D) {
        self.offset = offset
        self.extent = extent
    }

    init(cStruct: VkRect2D) {
        self.offset = Offset2D(cStruct: cStruct.offset)
        self.extent = Extent2D(cStruct: cStruct.extent)
    }

    public func withCStruct<R, E: Error>(_ body: (UnsafePointer<VkRect2D>) throws(E) -> R) throws(E) -> R {
        try self.offset.withCStruct { ptr_offset throws(E) in
            try self.extent.withCStruct { ptr_extent throws(E) in
                var cStruct = VkRect2D()
                cStruct.offset = ptr_offset.pointee
                cStruct.extent = ptr_extent.pointee
                return try body(&cStruct)
            }
        }
    }
}

public struct ClearRect: CStructConvertible {
    public typealias CStruct = VkClearRect

    public let rect: Rect2D
    public let baseArrayLayer: UInt32
    public let layerCount: UInt32

    public init(rect: Rect2D, baseArrayLayer: UInt32, layerCount: UInt32) {
        self.rect = rect
        self.baseArrayLayer = baseArrayLayer
        self.layerCount = layerCount
    }

    init(cStruct: VkClearRect) {
        self.rect = Rect2D(cStruct: cStruct.rect)
        self.baseArrayLayer = cStruct.baseArrayLayer
        self.layerCount = cStruct.layerCount
    }

    public func withCStruct<R, E: Error>(_ body: (UnsafePointer<VkClearRect>) throws(E) -> R) throws(E) -> R {
        try self.rect.withCStruct { ptr_rect throws(E) in
            var cStruct = VkClearRect()
            cStruct.rect = ptr_rect.pointee
            cStruct.baseArrayLayer = self.baseArrayLayer
            cStruct.layerCount = self.layerCount
            return try body(&cStruct)
        }
    }
}

public struct ComponentMapping: CStructConvertible {
    public typealias CStruct = VkComponentMapping

    public let r: ComponentSwizzle
    public let g: ComponentSwizzle
    public let b: ComponentSwizzle
    public let a: ComponentSwizzle

    public init(r: ComponentSwizzle, g: ComponentSwizzle, b: ComponentSwizzle, a: ComponentSwizzle) {
        self.r = r
        self.g = g
        self.b = b
        self.a = a
    }

    init(cStruct: VkComponentMapping) {
        self.r = ComponentSwizzle(rawValue: unsafeBitCast(cStruct.r, to: UInt32.self))!
        self.g = ComponentSwizzle(rawValue: unsafeBitCast(cStruct.g, to: UInt32.self))!
        self.b = ComponentSwizzle(rawValue: unsafeBitCast(cStruct.b, to: UInt32.self))!
        self.a = ComponentSwizzle(rawValue: unsafeBitCast(cStruct.a, to: UInt32.self))!
    }

    public func withCStruct<R, E: Error>(_ body: (UnsafePointer<VkComponentMapping>) throws(E) -> R) throws(E) -> R {
        var cStruct = VkComponentMapping()
        cStruct.r = VkComponentSwizzle(rawValue: VkComponentSwizzle.RawValue(self.r.rawValue))
        cStruct.g = VkComponentSwizzle(rawValue: VkComponentSwizzle.RawValue(self.g.rawValue))
        cStruct.b = VkComponentSwizzle(rawValue: VkComponentSwizzle.RawValue(self.b.rawValue))
        cStruct.a = VkComponentSwizzle(rawValue: VkComponentSwizzle.RawValue(self.a.rawValue))
        return try body(&cStruct)
    }
}

